import{_ as a,o as i,c as t,ah as s}from"./chunks/framework.Sdx4l2LO.js";const p=JSON.parse('{"title":"ISSUE-042: Duplicate Instance Fatal Error on Game Launch","description":"","frontmatter":{},"headers":[],"relativePath":"issues/ISSUE-042-duplicate-instance-fatal-error.md","filePath":"issues/ISSUE-042-duplicate-instance-fatal-error.md","lastUpdated":1774803703000}'),n={name:"issues/ISSUE-042-duplicate-instance-fatal-error.md"};function l(o,e,r,c,h,d){return i(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="issue-042-duplicate-instance-fatal-error-on-game-launch" tabindex="-1">ISSUE-042: Duplicate Instance Fatal Error on Game Launch <a class="header-anchor" href="#issue-042-duplicate-instance-fatal-error-on-game-launch" aria-label="Permalink to &quot;ISSUE-042: Duplicate Instance Fatal Error on Game Launch&quot;">​</a></h1><p><strong>Status</strong>: Reported <strong>Priority</strong>: High <strong>Component</strong>: Launcher (<code>launch-game</code> command, test harness) <strong>Related ADR</strong>: ADR-013-duplicate-instance-detection-bypass.md</p><h2 id="problem-description" tabindex="-1">Problem Description <a class="header-anchor" href="#problem-description" aria-label="Permalink to &quot;Problem Description&quot;">​</a></h2><p>When launching Diplomacy is Not an Option (DINO) via the <code>launch-game</code> PowerShell command or automated test launcher, the game fails with a fatal error:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Another instance is already running. Only one instance of the game is allowed.</span></span></code></pre></div><p>This prevents:</p><ul><li>Running automated tests that need to launch and close the game multiple times</li><li>Quick iteration during development (kill, fix, relaunch cycle)</li><li>CI/CD pipelines that spawn game instances for integration tests</li><li>Parallel test execution on shared machines</li></ul><h3 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h3><ul><li><strong>Windows 11 Pro</strong> (10.0.28020)</li><li><strong>DINO version</strong>: Latest (2026-03 branch)</li><li><strong>Steam client</strong>: Running (standard configuration)</li><li><strong>Game path</strong>: <code>G:\\SteamLibrary\\steamapps\\common\\Diplomacy is Not an Option</code></li><li><strong>BepInEx</strong>: 5.4.23.5 (standard GitHub release)</li><li><strong>DINOForge</strong>: Latest main branch</li></ul><h3 id="root-cause" tabindex="-1">Root Cause <a class="header-anchor" href="#root-cause" aria-label="Permalink to &quot;Root Cause&quot;">​</a></h3><p>Diplomacy is Not an Option uses a Win32 named mutex to enforce single-instance constraints. When the game process is killed (even via <code>Stop-Process -Force</code>), the kernel may not immediately release the mutex, causing subsequent launch attempts to fail during game initialization before BepInEx even loads.</p><p>See ADR-013 for full technical analysis.</p><h2 id="steps-to-reproduce" tabindex="-1">Steps to Reproduce <a class="header-anchor" href="#steps-to-reproduce" aria-label="Permalink to &quot;Steps to Reproduce&quot;">​</a></h2><ol><li>Open PowerShell</li><li>Run <code>.claude/commands/launch-game.md</code> (or equivalent):<div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Stop-Process</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Name </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Diplomacy is Not an Option&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Force </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ErrorAction SilentlyContinue</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Start-Sleep</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Seconds </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Start-Process</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FilePath </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;G:\\SteamLibrary\\steamapps\\common\\Diplomacy is Not an Option\\Diplomacy is Not an Option.exe&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WorkingDirectory </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;G:\\SteamLibrary\\steamapps\\common\\Diplomacy is Not an Option&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ArgumentList </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-bepinex&quot;</span></span></code></pre></div></li><li>Game window appears briefly, then closes with &quot;Another instance is already running&quot; error</li><li>No DINOForge bootstrap logs appear in <code>BepInEx/dinoforge_debug.log</code></li></ol><p><strong>Expected behavior</strong>: Game should launch successfully and BepInEx + DINOForge should initialize</p><h2 id="root-cause-analysis" tabindex="-1">Root Cause Analysis <a class="header-anchor" href="#root-cause-analysis" aria-label="Permalink to &quot;Root Cause Analysis&quot;">​</a></h2><h3 id="win32-mutex-semantics" tabindex="-1">Win32 Mutex Semantics <a class="header-anchor" href="#win32-mutex-semantics" aria-label="Permalink to &quot;Win32 Mutex Semantics&quot;">​</a></h3><ol><li>Game calls <code>CreateMutex(&quot;Global\\DiplomaXXX&quot;, ...)</code> on startup</li><li>If mutex already exists (from previous game instance), game exits with fatal error</li><li>When game process dies, kernel&#39;s mutex table is not immediately flushed</li><li>New instance tries to create the same mutex, finds it still in kernel table, fails</li><li>Sleep (3 seconds) is insufficient on most systems; mutex may persist for 10-30+ seconds</li></ol><h3 id="why-stop-process-alone-fails" tabindex="-1">Why <code>Stop-Process</code> Alone Fails <a class="header-anchor" href="#why-stop-process-alone-fails" aria-label="Permalink to &quot;Why `Stop-Process` Alone Fails&quot;">​</a></h3><ul><li><code>Stop-Process -Force</code> kills the process immediately</li><li>Kernel-level resources (mutexes, file handles) held by the process are queued for release</li><li>Release is asynchronous and may not complete within a few seconds</li><li>New instance attempts to acquire mutex before kernel has released it from the old process</li></ul><h3 id="why-direct-exe-launch-still-fails" tabindex="-1">Why Direct Exe Launch Still Fails <a class="header-anchor" href="#why-direct-exe-launch-still-fails" aria-label="Permalink to &quot;Why Direct Exe Launch Still Fails&quot;">​</a></h3><ul><li>Even calling <code>.exe</code> directly (bypassing Steam launcher) doesn&#39;t bypass the game&#39;s own mutex check</li><li>DINO&#39;s init code (static initializer or Unity player startup) enforces the constraint</li><li>This is game-level protection, not Steam-level</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h2><p>The <code>launch-game</code> command is considered <strong>fixed</strong> when:</p><ol><li><strong>Reliability</strong>: Launching <code>launch-game.ps1</code> twice in succession (with 5-second gap) succeeds both times without &quot;another instance&quot; error</li><li><strong>Speed</strong>: Total time from <code>launch-game</code> invocation to &quot;Awake completed&quot; in logs is &lt; 15 seconds (including any necessary waits)</li><li><strong>Automation-safe</strong>: The fix works when called from a PowerShell script without user intervention</li><li><strong>No side effects</strong>: Game runs normally after launch; no crashes, missing features, or gameplay issues</li><li><strong>Documentation</strong>: Solution documented in <code>CLAUDE.md</code> or new <code>launch-game.md</code> version</li><li><strong>Fallback</strong>: If primary method fails, has a documented fallback (e.g., &quot;increase sleep&quot; or &quot;restart Steam&quot;)</li></ol><h2 id="implementation-plan" tabindex="-1">Implementation Plan <a class="header-anchor" href="#implementation-plan" aria-label="Permalink to &quot;Implementation Plan&quot;">​</a></h2><h3 id="phase-1-investigation-before-code" tabindex="-1">Phase 1: Investigation (before code) <a class="header-anchor" href="#phase-1-investigation-before-code" aria-label="Permalink to &quot;Phase 1: Investigation (before code)&quot;">​</a></h3><ol><li><p><strong>Identify mutex name</strong></p><ul><li>Use Sysinternals <code>Handle.exe</code> to enumerate Win32 mutexes</li><li>Launch game and capture all mutexes created</li><li>Determine if name is static or per-instance</li><li>Document findings in ADR-013</li></ul></li><li><p><strong>Test P/Invoke approach</strong></p><ul><li>Write PowerShell proof-of-concept using <code>OpenMutex</code> + <code>ReleaseMutex</code></li><li>Test on real DINO instance</li><li>Determine if kernel allows non-owning process to release mutex</li><li>Document success/failure in ADR-013</li></ul></li><li><p><strong>Empirical timing measurement</strong></p><ul><li>Kill game and measure how long mutex persists in kernel table</li><li>Test multiple runs to find average persistence time</li><li>Determine safe minimum sleep duration</li></ul></li></ol><h3 id="phase-2-implementation" tabindex="-1">Phase 2: Implementation <a class="header-anchor" href="#phase-2-implementation" aria-label="Permalink to &quot;Phase 2: Implementation&quot;">​</a></h3><p><strong>Choose approach based on Phase 1 results:</strong></p><ul><li><strong>If P/Invoke works</strong>: Integrate mutex release into <code>launch-game.ps1</code> (see SPEC-duplicate-instance-bypass.md)</li><li><strong>If P/Invoke fails</strong>: Use empirical sleep duration (10-15 seconds) instead</li><li><strong>As fallback</strong>: Implement copy-exe or other workaround</li></ul><h3 id="phase-3-testing" tabindex="-1">Phase 3: Testing <a class="header-anchor" href="#phase-3-testing" aria-label="Permalink to &quot;Phase 3: Testing&quot;">​</a></h3><ol><li><p><strong>Unit test</strong> (PowerShell):</p><ul><li>Create test script that launches game 5 times with 5-second gaps</li><li>Verify all 5 launches succeed</li><li>Run on Windows 10, Windows 11, and GitHub Actions runner (if applicable)</li></ul></li><li><p><strong>Integration test</strong> (C#):</p><ul><li>Add <code>LaunchGameTests.cs</code> to <code>src/Tests/</code></li><li>Test game startup via <code>launch-game</code> command</li><li>Verify BepInEx initialization via log polling</li><li>Test cleanup (game exit) doesn&#39;t break subsequent launch</li></ul></li><li><p><strong>Manual verification</strong>:</p><ul><li>Test on developer machine (this one)</li><li>Test with Steam running and not running</li><li>Test after Windows restart</li></ul></li></ol><h3 id="phase-4-documentation" tabindex="-1">Phase 4: Documentation <a class="header-anchor" href="#phase-4-documentation" aria-label="Permalink to &quot;Phase 4: Documentation&quot;">​</a></h3><ol><li><p>Update <code>.claude/commands/launch-game.md</code>:</p><ul><li>Document mutex release mechanism</li><li>Add <code>--force</code> flag if applicable</li><li>Add troubleshooting section</li></ul></li><li><p>Update <code>CLAUDE.md</code>:</p><ul><li>Add note about mutex behavior</li><li>Add launch-game command description</li></ul></li><li><p>Add to <code>docs/troubleshooting.md</code>:</p><ul><li>&quot;Game won&#39;t launch: &#39;another instance&#39; error&quot;</li><li>Step-by-step resolution</li></ul></li></ol><h3 id="phase-5-release" tabindex="-1">Phase 5: Release <a class="header-anchor" href="#phase-5-release" aria-label="Permalink to &quot;Phase 5: Release&quot;">​</a></h3><ol><li>Test on real Windows 11 system</li><li>Commit to main branch with updated <code>launch-game.md</code></li><li>Close this issue when all tests pass</li></ol><h2 id="estimated-effort" tabindex="-1">Estimated Effort <a class="header-anchor" href="#estimated-effort" aria-label="Permalink to &quot;Estimated Effort&quot;">​</a></h2><ul><li>Phase 1 (Investigation): 1-2 hours</li><li>Phase 2 (Implementation): 1 hour (once investigation complete)</li><li>Phase 3 (Testing): 1-2 hours</li><li>Phase 4 (Documentation): 30 minutes</li><li>Phase 5 (Release): 15 minutes</li></ul><p><strong>Total</strong>: ~4-6 hours</p><h2 id="blockers" tabindex="-1">Blockers <a class="header-anchor" href="#blockers" aria-label="Permalink to &quot;Blockers&quot;">​</a></h2><p>None identified. This is a pure launcher/testing issue, not a gameplay or core framework blocker.</p><h2 id="related-issues" tabindex="-1">Related Issues <a class="header-anchor" href="#related-issues" aria-label="Permalink to &quot;Related Issues&quot;">​</a></h2><ul><li>None currently open</li></ul><h2 id="related-adrs" tabindex="-1">Related ADRs <a class="header-anchor" href="#related-adrs" aria-label="Permalink to &quot;Related ADRs&quot;">​</a></h2><ul><li><strong>ADR-013</strong> — Architectural decision for mutex bypass strategy</li><li><strong>SPEC-duplicate-instance-bypass.md</strong> — Technical specification and code</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><strong>Win32 Mutex docs</strong>: <a href="https://docs.microsoft.com/en-us/windows/win32/sync/named-mutexes" target="_blank" rel="noreferrer">https://docs.microsoft.com/en-us/windows/win32/sync/named-mutexes</a></li><li><strong>Sysinternals Handle</strong>: <a href="https://docs.microsoft.com/en-us/sysinternals/downloads/handle" target="_blank" rel="noreferrer">https://docs.microsoft.com/en-us/sysinternals/downloads/handle</a></li><li><strong>Current launch-game command</strong>: <code>.claude/commands/launch-game.md</code></li></ul>',48)])])}const m=a(n,[["render",l]]);export{p as __pageData,m as default};
